int main() {
    int n;
    int a[MAXN];
    int comp[MAXN];
    int comp_min[MAXN];
    int comp_size[MAXN];
    int comp_elems[MAXN][MAXN];
    int comp_count = 0;
    int adj[MAXN][MAXN];
    int deg[MAXN];

    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
        comp[i] = -1;
        deg[i] = 0;
    }

    // build adjacency based on gcd > 1
    for (int i = 0; i < n; i++) {
        for (int j = i+1; j < n; j++) {
            if (gcd(a[i], a[j]) > 1) {
                adj[i][deg[i]++] = j;
                adj[j][deg[j]++] = i;
            }
        }
    }

    // DFS to find components
    int stack[MAXN], top;
    for (int i = 0; i < n; i++) {
        if (comp[i] == -1) {
            top = 0;
            stack[top++] = i;
            comp[i] = comp_count;
            comp_size[comp_count] = 0;
            comp_min[comp_count] = 1000000000;
            while (top > 0) {
                int v = stack[--top];
                comp_elems[comp_count][comp_size[comp_count]++] = a[v];
                if (a[v] < comp_min[comp_count]) comp_min[comp_count] = a[v];
                for (int k = 0; k < deg[v]; k++) {
                    int u = adj[v][k];
                    if (comp[u] == -1) {
                        comp[u] = comp_count;
                        stack[top++] = u;
                    }
                }
            }
            comp_count++;
        }
    }

    // sort each component descending
    for (int c = 0; c < comp_count; c++) {
        qsort(comp_elems[c], comp_size[c], sizeof(int), cmp_desc);
    }

    // order components by their minimum element
    int order[MAXN];
    for (int i = 0; i < comp_count; i++) order[i] = i;
    for (int i = 0; i < comp_count; i++) {
        for (int j = i+1; j < comp_count; j++) {
            if (comp_min[order[i]] > comp_min[order[j]]) {
                int tmp = order[i];
                order[i] = order[j];
                order[j] = tmp;
            }
        }
    }

    // output
    for (int i = 0; i < comp_count; i++) {
        int c = order[i];
        for (int j = 0; j < comp_size[c]; j++) {
            printf("%d ", comp_elems[c][j]);
        }
    }
    printf("\n");

