typedef long long ll;

static ll gcdll(ll a, ll b) {
    while (b) {
        ll t = a % b;
        a = b;
        b = t;
    }
    return a;
}

static int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll *)a;
    ll y = *(const ll *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

/*
Key observation:

If two numbers are coprime, Aoki can swap adjacent occurrences of them.
Thus, considering the current sequence, any inversion pair (x before y with x < y)
such that gcd(x,y)=1 can be corrected by Aoki to make the sequence lexicographically larger.

So the eventual sequence under Aoki's optimal play is exactly a sequence with no adjacent-swappable
improvement left; equivalently, for every pair i<j with gcd(B[i],B[j])=1, we must have B[i] >= B[j].
That means all coprime pairs must appear in non-increasing order.

Define a graph on positions' values: edge between values if gcd=1.
Then for every connected component in this graph (on the multiset elements), all those elements
must appear in non-increasing order relative to each other in the final sequence, because along a path
of coprime relations, Aoki can bubble larger ones leftward through smaller compatible ones.

Takahashi chooses the initial arrangement. Since Aoki can only swap coprime adjacent pairs,
elements from different "non-coprime-closure" blocks cannot constrain each other unless there is gcd=1.
The correct minimax characterization is:

- Build graph on indices/elements, edge if gcd(A_i,A_j)=1.
- Connected components of this graph are the sets whose internal relative order Aoki can force into
  non-increasing order by value.
- Takahashi can interleave these components arbitrarily initially, and Aoki cannot move elements across
  components because no swap sequence can pass through without some gcd=1 connection; hence components
  behave like indivisible color classes whose internal output order is descending.
- Therefore Takahashi should merge these descending component sequences to obtain the lexicographically
  smallest possible global sequence, i.e. always take the smallest available front element among components.

This yields:
1) Find connected components in graph gcd=1.
2) For each component, collect values and sort descending.
3) Perform k-way merge choosing smallest current head each step.

N constraints are not provided here; we implement O(N^2 alpha(N) + N log N), suitable for moderate N.
*/

typedef struct {
    int p, r;
} DSU;

static void dsu_init(DSU *d, int n) {
    for (int i = 0; i < n; i++) {
        d[i].p = i;
        d[i].r = 0;
    }
}

static int dsu_find(DSU *d, int x) {
    if (d[x].p != x) d[x].p = dsu_find(d, d[x].p);
    return d[x].p;
}

static void dsu_union(DSU *d, int a, int b) {
    a = dsu_find(d, a);
    b = dsu_find(d, b);
    if (a == b) return;
    if (d[a].r < d[b].r) {
        d[a].p = b;
    } else if (d[a].r > d[b].r) {
        d[b].p = a;
    } else {
        d[b].p = a;
        d[a].r++;
    }
}

typedef struct {
    ll *v;
    int sz;
    int idx;
} Comp;

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    ll *A = (ll *)malloc(sizeof(ll) * N);
    for (int i = 0; i < N; i++) scanf("%lld", &A[i]);

    DSU *dsu = (DSU *)malloc(sizeof(DSU) * N);
    dsu_init(dsu, N);

    for (int i = 0; i < N; i++) {
        for (int j = i + 1; j < N; j++) {
            if (gcdll(A[i], A[j]) == 1) {
                dsu_union(dsu, i, j);
            }
        }
    }

    int *root_id = (int *)malloc(sizeof(int) * N);
    for (int i = 0; i < N; i++) root_id[i] = -1;

    int comps = 0;
    for (int i = 0; i < N; i++) {
        int r = dsu_find(dsu, i);
        if (root_id[r] == -1) root_id[r] = comps++;
    }

    int *cnt = (int *)calloc(comps, sizeof(int));
    for (int i = 0; i < N; i++) {
        int id = root_id[dsu_find(dsu, i)];
        cnt[id]++;
    }

    Comp *C = (Comp *)malloc(sizeof(Comp) * comps);
    for (int i = 0; i < comps; i++) {
        C[i].v = (ll *)malloc(sizeof(ll) * cnt[i]);
        C[i].sz = 0;
        C[i].idx = 0;
    }

    for (int i = 0; i < N; i++) {
        int id = root_id[dsu_find(dsu, i)];
        C[id].v[C[id].sz++] = A[i];
    }

    for (int i = 0; i < comps; i++) {
        qsort(C[i].v, C[i].sz, sizeof(ll), cmp_ll);
        /* reverse to descending */
        for (int l = 0, r = C[i].sz - 1; l < r; l++, r--) {
            ll t = C[i].v[l];
            C[i].v[l] = C[i].v[r];
            C[i].v[r] = t;
        }
    }

    /* k-way merge by smallest current head */
    for (int pos = 0; pos < N; pos++) {
        int best = -1;
        for (int i = 0; i < comps; i++) {
            if (C[i].idx >= C[i].sz) continue;
            if (best == -1 || C[i].v[C[i].idx] < C[best].v[C[best].idx]) {
                best = i;
            }
        }
        if (pos) printf(" ");
        printf("%lld", C[best].v[C[best].idx]);
        C[best].idx++;
    }
    printf("\n");

    for (int i = 0; i < comps; i++) free(C[i].v);
    free(C);
    free(cnt);
    free(root_id);
    free(dsu);
    free(A);
    return 0;
}

