vector<int> spf; // smallest prime factor

void sieve(int n) {
    spf.resize(n+1);
    iota(spf.begin(), spf.end(), 0);
    for (int i=2; i*i<=n; i++) 
        if (spf[i]==i)
            for (int j=i*i; j<=n; j+=i)
                if (spf[j]==j) spf[j]=i;
}

vector<int> factorize(int x) {
    vector<int> res;
    while (x > 1) {
        int p = spf[x];
        res.push_back(p);
        while (x % p == 0) x /= p;
    }
    return res;
}

