#include <bits/stdc++.h>
using namespace std;

using ll = long long;

static bool coprime_ll(ll a, ll b) {
    return std::gcd(a, b) == 1;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<ll> A(N);
    for (int i = 0; i < N; ++i) cin >> A[i];

    sort(A.begin(), A.end());

    // Build graph: edge between values that are NOT coprime.
    // If two numbers are in different connected components of this graph,
    // then by swapping adjacent coprime pairs repeatedly, their relative order
    // can be changed arbitrarily. Numbers inside the same component must keep
    // their relative order from Takahashi's initial arrangement.
    //
    // Therefore, after Takahashi chooses an ordering, Aoki can transform it into
    // any sequence obtained by interleaving the per-component subsequences while
    // preserving order inside each component.
    //
    // Takahashi wants lexicographically smallest final sequence, Aoki largest.
    // Optimal play results in:
    // - For each component, Takahashi should arrange its elements increasingly.
    // - Aoki then greedily chooses the largest possible current head among components.
    //
    // Since A is sorted globally, extracting elements by component from this sorted
    // list already gives each component in increasing order.

    vector<int> comp(N, -1);
    int cc = 0;
    for (int i = 0; i < N; ++i) {
        if (comp[i] != -1) continue;
        queue<int> q;
        q.push(i);
        comp[i] = cc;
        while (!q.empty()) {
            int v = q.front();
            q.pop();
            for (int u = 0; u < N; ++u) {
                if (comp[u] == -1 && !coprime_ll(A[v], A[u])) {
                    comp[u] = cc;
                    q.push(u);
                }
            }
        }
        ++cc;
    }

    vector<vector<ll>> groups(cc);
    for (int i = 0; i < N; ++i) groups[comp[i]].push_back(A[i]);

    // Current pointer for each component.
    vector<int> ptr(cc, 0);

    // Aoki picks lexicographically largest possible final sequence:
    // at each step choose the largest current head among non-empty components.
    vector<ll> ans;
    ans.reserve(N);

    for (int step = 0; step < N; ++step) {
        ll bestVal = -1;
        int bestComp = -1;
        for (int c = 0; c < cc; ++c) {
            if (ptr[c] < (int)groups[c].size()) {
                ll v = groups[c][ptr[c]];
                if (bestComp == -1 || v > bestVal) {
                    bestVal = v;
                    bestComp = c;
                }
            }
        }
        ans.push_back(bestVal);
        ptr[bestComp]++;
    }

    for (int i = 0; i < N; ++i) {
        if (i) cout << ' ';
        cout << ans[i];
    }
    cout << '\n';
    return 0;
}

