public class Main {
    static int gcd(int a, int b) { return b == 0 ? a : gcd(b, a % b); }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = sc.nextInt();

        // Takahashi sorts in decreasing order
        Arrays.sort(a);
        // reverse
        for (int i = 0; i < n/2; i++) { int t=a[i]; a[i]=a[n-1-i]; a[n-1-i]=t; }

        List<Integer> list = new ArrayList<>();
        for (int x : a) list.add(x);

        List<Integer> result = new ArrayList<>();
        while (!list.isEmpty()) {
            for (int i = 0; i < list.size(); i++) {
                boolean canMove = true;
                for (int j = 0; j < i; j++) {
                    if (gcd(list.get(j), list.get(i)) > 1) { canMove = false; break; }
                }
                if (canMove) {
                    // find max among all movable
                    int best = -1, bestIdx = -1;
                    for (int k = i; k < list.size(); k++) {
                        boolean ok = true;
                        for (int j = 0; j < k; j++) if (gcd(list.get(j),list.get(k))>1){ok=false;break;}
                        if (ok && (best==-1||list.get(k)>best)){best=list.get(k);bestIdx=k;}
                    }
                    result.add(list.remove(bestIdx));
                    break;
                }
            }
        }
        StringBuilder sb = new StringBuilder();
        for (int x : result) sb.append(x).append("\n");
        System.out.print(sb);
    }
}

