public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine());
        int[] A = new int[N];
        StringTokenizer st = new StringTokenizer(br.readLine());
        for (int i = 0; i < N; i++) {
            A[i] = Integer.parseInt(st.nextToken());
        }

        int maxVal = 0;
        for (int v : A) maxVal = Math.max(maxVal, v);

        // Sieve smallest prime factor
        int[] spf = new int[maxVal + 1];
        for (int i = 2; i <= maxVal; i++) spf[i] = i;
        for (int i = 2; i * i <= maxVal; i++) {
            if (spf[i] == i) {
                for (int j = i * i; j <= maxVal; j += i) {
                    if (spf[j] == j) spf[j] = i;
                }
            }
        }

        // Union-Find on indices
        int[] parent = new int[N];
        int[] size = new int[N];
        for (int i = 0; i < N; i++) {
            parent[i] = i;
            size[i] = 1;
        }

        // map from prime factor to first index having that factor
        Map<Integer, Integer> primeToIdx = new HashMap<>();
        for (int i = 0; i < N; i++) {
            int x = A[i];
            Set<Integer> primes = new HashSet<>();
            while (x > 1) {
                int p = spf[x];
                primes.add(p);
                while (x % p == 0) x /= p;
            }
            for (int p : primes) {
                if (primeToIdx.containsKey(p)) {
                    union(parent, size, i, primeToIdx.get(p));
                } else {
                    primeToIdx.put(p, i);
                }
            }
        }

        // Group by component root
        Map<Integer, List<Integer>> comp = new HashMap<>();
        for (int i = 0; i < N; i++) {
            int root = find(parent, i);
            comp.computeIfAbsent(root, k -> new ArrayList<>()).add(A[i]);
        }

        // Sort each component descending and find max
        List<int[]> compInfo = new ArrayList<>();
        for (List<Integer> list : comp.values()) {
            Collections.sort(list, Collections.reverseOrder());
            int maxEl = list.get(0);
            compInfo.add(new int[]{maxEl, list.size()});
        }

        // Sort components by max ascending
        compInfo.sort(Comparator.comparingInt(a -> a[0]));

        // Build result: for each component in sorted order, output its sorted descending numbers
        // We need to output in the order Takahashi chooses: components sorted by max ascending.
        // But we must map back to the actual lists sorted descending.
        // Since we lost the actual list after sorting compInfo, let's redo more carefully.

        // Better: store lists in a map and then sort keys by max.
        List<Integer> compRoots = new ArrayList<>(comp.keySet());
        compRoots.sort(Comparator.comparingInt(r -> Collections.max(comp.get(r))));

        StringBuilder sb = new StringBuilder();
        for (int root : compRoots) {
            List<Integer> list = comp.get(root);
            list.sort(Collections.reverseOrder());
            for (int v : list) {
                sb.append(v).append(" ");
            }
        }
        System.out.println(sb.toString().trim());
    }

    static int find(int[] parent, int x) {
        if (parent[x] != x) parent[x] = find(parent, parent[x]);
        return parent[x];
    }

    static void union(int[] parent, int[] size, int a, int b) {
        a = find(parent, a);
        b = find(parent, b);
        if (a == b) return;
        if (size[a] < size[b]) {
            int tmp = a; a = b; b = tmp;
        }
        parent[b] = a;
        size[a] += size[b];
    }
}

