public class Main {
    // DSU for gcd>1 connectivity
    static class DSU {
        int[] p, sz;
        DSU(int n) {
            p = new int[n];
            sz = new int[n];
            for (int i = 0; i < n; i++) {
                p[i] = i;
                sz[i] = 1;
            }
        }
        int find(int x) {
            while (p[x] != x) {
                p[x] = p[p[x]];
                x = p[x];
            }
            return x;
        }
        void union(int a, int b) {
            a = find(a);
            b = find(b);
            if (a == b) return;
            if (sz[a] < sz[b]) {
                int t = a; a = b; b = t;
            }
            p[b] = a;
            sz[a] += sz[b];
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        int[] A = new int[N];
        for (int i = 0; i < N; i++) A[i] = fs.nextInt();

        // Key fact:
        // Define graph on indices: edge i-j if gcd(A[i], A[j]) > 1.
        // If two values are in different connected components of this graph,
        // they can cross each other by swaps through coprime adjacency.
        // If they are in the same component, their relative order is invariant.
        //
        // Therefore:
        // - Each connected component forms a chain whose internal relative order is fixed.
        // - Takahashi can choose any interleaving of these chains.
        // - Aoki, wanting lexicographically largest result, will realize the lexicographically
        //   largest merge of these chains.
        // Takahashi chooses the initial arrangement to minimize that final largest merge.
        //
        // This is achieved by first sorting the values inside each component by their original
        // component-order (fixed), and then the game value becomes simply the lexicographically
        // smallest sequence obtainable by partitioning into such invariant chains.
        //
        // Equivalent constructive result:
        // Build connected components by gcd>1, then output the lexicographically smallest merge
        // of the component sequences, where each component sequence is its values sorted ascending.
        //
        // Since Takahashi may arrange arbitrarily before Aoki starts, he should order each
        // component internally ascending as well; then Aoki cannot change internal order.
        // The final answer is the lexicographically smallest merge of these ascending sequences.

        DSU dsu = new DSU(N);
        for (int i = 0; i < N; i++) {
            for (int j = i + 1; j < N; j++) {
                if (gcd(A[i], A[j]) > 1) dsu.union(i, j);
            }
        }

        Map<Integer, ArrayList<Integer>> mp = new HashMap<>();
        for (int i = 0; i < N; i++) {
            int r = dsu.find(i);
            mp.computeIfAbsent(r, k -> new ArrayList<>()).add(A[i]);
        }

        ArrayList<int[]> seqs = new ArrayList<>();
        for (ArrayList<Integer> list : mp.values()) {
            Collections.sort(list);
            int[] s = new int[list.size()];
            for (int i = 0; i < s.length; i++) s[i] = list.get(i);
            seqs.add(s);
        }

        // Lexicographically smallest merge of multiple sequences:
        // repeatedly choose sequence whose remaining suffix is lexicographically smallest.
        int m = seqs.size();
        int[] ptr = new int[m];
        StringBuilder sb = new StringBuilder();

        for (int step = 0; step < N; step++) {
            int best = -1;
            for (int i = 0; i < m; i++) {
                if (ptr[i] == seqs.get(i).length) continue;
                if (best == -1 || compare(seqs.get(i), ptr[i], seqs.get(best), ptr[best]) < 0) {
                    best = i;
                }
            }
            if (step > 0) sb.append(' ');
            sb.append(seqs.get(best)[ptr[best]++]);
        }

        System.out.println(sb.toString());
    }

    static int compare(int[] a, int ia, int[] b, int ib) {
        int na = a.length, nb = b.length;
        while (ia < na && ib < nb) {
            if (a[ia] != b[ib]) return Integer.compare(a[ia], b[ib]);
            ia++;
            ib++;
        }
        if (ia == na && ib == nb) return 0;
        return ia == na ? -1 : 1;
    }

    static int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

import sys
from collections import defaultdict

def sieve_primes(limit):
    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(limit**0.5) + 1):
        if is_prime[i]:
            for j in range(i*i, limit+1, i):
                is_prime[j] = False
    return [i for i, v in enumerate(is_prime) if v]

def main():
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    A = list(map(int, input_data[1:]))

    if n == 0:
        print()
        return

    max_val = max(A)
    primes = sieve_primes(max_val)

    # Map each prime to an index for union-find
    prime_to_idx = {p: i for i, p in enumerate(primes)}
    m = len(primes)
    parent = list(range(m + n))  # extra n slots for numbers themselves

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx != ry:
            parent[ry] = rx

    # Connect numbers to their prime factors
    for i, val in enumerate(A):
        num_node = m + i
        temp = val
        p = 2
        while p * p <= temp:
            if temp % p == 0:
                if p in prime_to_idx:
                    union(num_node, prime_to_idx[p])
                while temp % p == 0:
                    temp //= p
            p += 1 if p == 2 else 2
        if temp > 1:
            if temp in prime_to_idx:
                union(num_node, prime_to_idx[temp])

    # Group numbers by component root
    comp_map = defaultdict(list)
    for i, val in enumerate(A):
        root = find(m + i)
        comp_map[root].append(val)

    # Sort each component ascending (Takahashi's optimal arrangement)
    for root in comp_map:
        comp_map[root].sort()

    # Order components by smallest element
    sorted_comps = sorted(comp_map.values(), key=lambda lst: lst[0])

    # Aoki reverses each component (descending order)
    result = []
    for comp in sorted_comps:
        result.extend(reversed(comp))

    print(' '.join(map(str, result)))

if __name__ == "__main__":
    main()
